package com.example.commerce.config; import io.swagger.v3.oas.models.*; import io.swagger.v3.oas.models.security.*; import org.springframework.context.annotation.*;
@Configuration public class OpenApiConfig {@Bean OpenAPI commerceApi(){return new OpenAPI().info(new Info().title("Smart Commerce API").version("1.0").description("Transactional order management API")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearerAuth"));}}
